        SetValue(MapVar(3), 1)
        XeenQuests.hook("q-d19.gongs")
        return
    end
    if continueStep ~= nil then
        evt.StatusText("The gong booms, and the echo dies away.", 4)
        evt.PlaySoundName("xeen_gong", -1270, -400, 256)
